"""The game's font, DejaVu Serif Bold, built in so every phone shows the same letters
(the phone app's pygame has no serif font of its own and fell back to a tiny one).
DejaVu fonts are free to use and share; their licence is kept below."""
import base64
import io
import zlib
import pygame

TTF = zlib.decompress(base64.b64decode(''))
_C = {}
SMALL_BOOST = 1.18                       # how much bigger small text is drawn (1.0 = as asked)


def font(size):
  """the game font at this pixel size (cached)"""
  size = max(6, int(size))
  if size <= 24:                               # small text is scaled up so it reads on a phone
    size = int(round(size * SMALL_BOOST))
  f = _C.get(size)
  if f is None:
    f = _C[size] = pygame.font.Font(io.BytesIO(TTF), size)
  return f


_SYSFONT = pygame.font.SysFont


def _sysfont(name, size, bold=False, italic=False, *a, **k):
  try:
    return font(size)
  except Exception:
    return _SYSFONT(name, size, bold, italic)


def install():
  """make every pygame.font.SysFont call in the game use the built-in font"""
  pygame.font.SysFont = _sysfont


